input.new_string:
def coerce_fs_path(value: str | Path | None) -> Path | None:
    """Translate WSL /mnt/<drive>/... and Windows X:\\... across the interop boundary.

    Claude Code / git may report the other OS's path when the same contest tree is
    opened from Windows and from WSL. The .repo privacy gate must still resolve.
    """
    if value is None:
        return None
    s = str(value).strip().strip('"')
    if not s:
        return None
    s_slash = s.replace("\\", "/")
    mnt = re.match(r"^/mnt/([A-Za-z])/(.*)$", s_slash)
    win = re.match(r"^([A-Za-z]):[\\/](.*)$", s)
    if os.name == "nt":
        if mnt:
            return Path(mnt.group(1).upper() + ":\\" + mnt.group(2).replace("/", "\\"))
        return Path(s)
    if win:
        return Path("/mnt/" + win.group(1).lower() + "/" + win.group(2).replace("\\", "/"))
    return Path(s)


def get_repo_root() -> Path | None:
    try:
        out = subprocess.check_output(["git", "rev-parse", "--show-toplevel"], stderr=subprocess.PIPE, text=True)
        return coerce_fs_path(out.strip())
    except Exception:
        return None

