def expand_cursor_event(raw_event: dict, fallback_ts: str) -> list[dict]:
    """Convert one Cursor agent-transcripts JSONL event to contest events.

    Cursor stores conversation JSONL under ~/.cursor/projects/<slug>/agent-transcripts/.
    Typical line shape (verified against local transcripts):
      {"role":"user"|"assistant","message":{"content":[{type:text|tool_use|thinking,...}]}}
    """
    if not isinstance(raw_event, dict):
        return []
    msg = raw_event.get("message")
    if isinstance(msg, str):
        msg = {"role": raw_event.get("role") or "user", "content": msg}
    elif not isinstance(msg, dict):
        content = raw_event.get("content")
        if content is None and raw_event.get("text"):
            content = raw_event.get("text")
        if content is None:
            return []
        msg = {"role": raw_event.get("role") or raw_event.get("type") or "system", "content": content}
    role = msg.get("role") or raw_event.get("role") or raw_event.get("type") or "system"
    synthetic = {
        "type": role,
        "timestamp": raw_event.get("timestamp") or raw_event.get("createdAt") or fallback_ts,
        "message": {**msg, "role": role},
    }
    return expand_claude_event(synthetic, fallback_ts)


