                [sys.executable, str(core_py), "--tool", "cursor"],
                input=payload, text=True, capture_output=True,
                env=child_env, cwd=str(dest),
            )
            if result.returncode == 0 and "captured" in (result.stderr or ""):
                success += 1
                print(f"  [cursor] {sid[:12]}  captured")
            elif result.returncode != 0:
